{
  "schema": 1,
  "title": "Configuration evaluation outcome from ordered validation facts",
  "inputs": {
    "request": "object",
    "policy": "object",
    "evidence": "array"
  },
  "rules": [
    {
      "id": "layer_unknown_precedes_later_checks",
      "target": "status",
      "claim": "An unknown key in any ordered layer fails with unknown_key before environment or final-type checks.",
      "when": {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "layer_keys_known"}, {"value": true}]}, {"value": false}]},
      "then": {"value": "unknown_key"},
      "evidence": ["dc34f34f"],
      "dependencies": ["work.py", "TASK.md"]
    },
    {
      "id": "environment_validation",
      "target": "status",
      "claim": "After layer keys pass, a nonempty environment override fails with environment unless enabled, known-keyed, and exactly parseable for the policy type.",
      "when": {"op": "and", "args": [
        {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "layer_keys_known"}, {"value": true}]}, {"value": true}]},
        {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "environment_present"}, {"value": false}]}, {"value": true}]},
        {"op": "or", "args": [
          {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "environment_allowed"}, {"value": false}]}, {"value": false}]},
          {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "environment_keys_known"}, {"value": false}]}, {"value": false}]},
          {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "environment_values_valid"}, {"value": false}]}, {"value": false}]}
        ]}
      ]},
      "then": {"value": "environment"},
      "evidence": ["dc34f34f"],
      "dependencies": ["work.py", "TASK.md"]
    },
    {
      "id": "final_exact_type_failure",
      "target": "status",
      "claim": "Only after all layers and valid environment overrides, an inexact final type fails with type; boolean is not integer.",
      "when": {"op": "and", "args": [
        {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "layer_keys_known"}, {"value": true}]}, {"value": true}]},
        {"op": "or", "args": [
          {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "environment_present"}, {"value": false}]}, {"value": false}]},
          {"op": "and", "args": [
            {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "environment_allowed"}, {"value": false}]}, {"value": true}]},
            {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "environment_keys_known"}, {"value": false}]}, {"value": true}]},
            {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "environment_values_valid"}, {"value": false}]}, {"value": true}]}
          ]}
        ]},
        {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "final_types_exact"}, {"value": false}]}, {"value": false}]}
      ]},
      "then": {"value": "type"},
      "evidence": ["dc34f34f"],
      "dependencies": ["work.py", "TASK.md"]
    },
    {
      "id": "successful_configuration",
      "target": "status",
      "claim": "Known layer keys, no environment error, and exact final types produce success while preserving false, zero, and empty strings.",
      "when": {"op": "and", "args": [
        {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "layer_keys_known"}, {"value": true}]}, {"value": true}]},
        {"op": "or", "args": [
          {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "environment_present"}, {"value": false}]}, {"value": false}]},
          {"op": "and", "args": [
            {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "environment_allowed"}, {"value": false}]}, {"value": true}]},
            {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "environment_keys_known"}, {"value": false}]}, {"value": true}]},
            {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "environment_values_valid"}, {"value": false}]}, {"value": true}]}
          ]}
        ]},
        {"op": "eq", "args": [{"op": "get", "args": [{"var": "request"}, {"value": "final_types_exact"}, {"value": false}]}, {"value": true}]}
      ]},
      "then": {"value": "ok"},
      "evidence": ["dc34f34f"],
      "dependencies": ["work.py", "TASK.md"]
    }
  ],
  "cases": [
    {"id": "unknown_layer_probe", "target": "status", "inputs": {"request": {"layer_keys_known": false, "environment_present": false, "final_types_exact": true}, "policy": {"environment": true}, "evidence": ["actual evaluate returned unknown_key for layer z"]}, "expected": "unknown_key", "evidence": ["dc34f34f"], "challenge": true},
    {"id": "unicode_environment_probe", "target": "status", "inputs": {"request": {"layer_keys_known": true, "environment_present": true, "environment_allowed": true, "environment_keys_known": true, "environment_values_valid": false, "final_types_exact": true}, "policy": {"environment": true}, "evidence": ["actual evaluate rejected Arabic-Indic digits"]}, "expected": "environment", "evidence": ["dc34f34f"], "challenge": true},
    {"id": "boolean_integer_probe", "target": "status", "inputs": {"request": {"layer_keys_known": true, "environment_present": false, "final_types_exact": false}, "policy": {"environment": true}, "evidence": ["actual evaluate rejected true for integer"]}, "expected": "type", "evidence": ["dc34f34f"], "challenge": true},
    {"id": "later_repair_probe", "target": "status", "inputs": {"request": {"layer_keys_known": true, "environment_present": true, "environment_allowed": true, "environment_keys_known": true, "environment_values_valid": true, "final_types_exact": true}, "policy": {"environment": true}, "evidence": ["actual environment -12 repaired prior invalid layer value"]}, "expected": "ok", "evidence": ["dc34f34f"], "challenge": true}
  ],
  "alternatives": [],
  "unresolved": ["The executable model consumes ordered-evaluation facts derived from a request; it does not independently normalize arbitrary raw layer objects. Behavior outside boolean/integer/string policy types is untested and intentionally unspecified."]
}
